ALTER TABLE "question_scoring" ADD CONSTRAINT "question_scoring_shape_valid" CHECK (("question_scoring"."points" is null and "question_scoring"."exact_score_points" is not null and "question_scoring"."normal_result_points" is not null and "question_scoring"."against_rival" is null and "question_scoring"."exact_score_points" > coalesce("question_scoring"."goal_difference_points", "question_scoring"."normal_result_points") and ("question_scoring"."goal_difference_points" is null or "question_scoring"."goal_difference_points" > "question_scoring"."normal_result_points")) or ("question_scoring"."points" is not null and "question_scoring"."exact_score_points" is null and "question_scoring"."goal_difference_points" is null and "question_scoring"."normal_result_points" is null));